import json
d={c['id']:c for c in json.load(open('verdicts/in/chunk_04.json'))}
N="nieustalone"
rows=[]
def add(id,werdykt,pew,www,usluga,typ,conox,img,linki,uzas,auta=N,odz=N,szyld=N,druk=N,sygnal="brak",hip=True):
    c=d[id]
    rows.append({"id":id,"firma":c['firma'],"kategoria":c['kategoria'],"werdykt":werdykt,"pewnosc":pew,
     "dowody":{"www":www,"auta":auta,"odziez":odz,"szyld_witryna":szyld,"druk_banery":druk},
     "aktualny_sygnal":sygnal,"usluga_gw":usluga,"hipoteza":hip,"typ_decyzji":typ,"co_nieustalone":conox,
     "obejrzane_obrazy":img,"linki":[c['strona']]+linki,"uzasadnienie":uzas})
add(224,"NIEUSTALONE","niska","Bowling w piwnicy w Veldhoven; zakładka Vacatures; na stronie grafika rekrutacyjna 'Werken bij de Flying Bowling' (plik z ścieżką uploads/2026/09). Brak zdjęć fasady.","Szyld / oklejenie witryny wejścia","lokalna firma","Zdjęcie fasady/wejścia (Street View lub Google Maps) i czy szyld jest czytelny z ulicy; czy personel nosi koszulki z logo.",1,["https://www.flying-bowling.nl/wp-content/uploads/2026/09/bowling.png","https://www.flying-bowling.nl/vacatures/"],"Obejrzana tylko grafika rekrutacyjna, która nie pokazuje fasady ani personelu. Nie ma dowodu ani na istniejącą reklamę zewnętrzną, ani na jej brak. Rekrutacja jest sygnałem bez daty, więc hipoteza, nie okazja.",druk="POTWIERDZONE: grafika rekrutacyjna online 'Werken bij de Flying Bowling' (https://www.flying-bowling.nl/wp-content/uploads/2026/09/bowling.png, data z ścieżki pliku: 2026/09); to materiał cyfrowy, nie druk")
add(283,"OPCJA ROZSZERZENIA","niska","Producent elektroniki high-tech (Brainport), 5 linii produkcyjnych; strona wspomina sponsoring odzieży (plik 'Kleding-en-accessoiresponsor-bijeenkomst-Snelle-Wiel-Bestronics3.jpg', 2024/12).","Odzież firmowa z haftem logo (softshelle/polo dla zespołu)","lokalna firma","Czy cały zespół ma jednolitą odzież z logo, czy tylko kierownictwo; wygląd fasady i szyldu w Veldhoven.",2,["https://www.bestronics.nl/wp-content/uploads/2024/12/Kleding-en-accessoiresponsor-bijeenkomst-Snelle-Wiel-Bestronics3.jpg","https://www.bestronics.nl/over-ons-en-het-team/"],"Na zdjęciu (upload 2024/12) jeden z mężczyzn ma czarną bluzę z wyhaftowanym napisem, który wygląda jak logo firmy, a pozostali są w fartuchach laboratoryjnych. To pokazuje, że część odzieży z logo już istnieje, ale nie wiadomo, czy dotyczy całego zespołu. Rekrutacja bez daty, więc hipoteza.",odz="POTWIERDZONE (częściowo): czarna bluza z napisem przypominającym logo Bestronics, pozostali w fartuchach; https://www.bestronics.nl/wp-content/uploads/2024/12/Kleding-en-accessoiresponsor-bijeenkomst-Snelle-Wiel-Bestronics3.jpg, data z ścieżki: 2024/12")
add(270,"NIEUSTALONE","niska","Agencja pracy (uitzendbureau) z biurem w Gemert; strona to głównie oferty pracy, opinie Google. Brak zdjęć biura ani floty w HTML.","Oklejenie witryny / szyld biura w Gemert","nieustalone","Zdjęcie fasady biura w Gemert i czy to samodzielna firma, czy część grupy; wygląd odzieży konsultantów.",0,["https://activus.nl/vacatures/"],"Z samej strony głównej nie da się ocenić reklamy fizycznej. Nie otwarto żadnego zdjęcia. Biuro stacjonarne może mieć potrzebę witryny, ale to tylko hipoteza.")
add(13,"OPCJA ROZSZERZENIA","niska","Hurtownia i montaż szkła (Helmond), strona z projektami, referencjami i vacatures; w ofercie m.in. druk na szkle i folie.","Oklejenie busów firmowych","lokalna firma","Czy busy montażowe mają oklejenie (zdjęcia floty, Street View); czy cała ekipa ma jednolitą odzież.",2,["https://www.eversenevers.nl/over-ons/","https://www.eversenevers.nl/projecten/","https://www.eversenevers.nl/wp-content/uploads/2020/07/Evers-Evers_Klein-4-e1595236386926-240x240.jpg"],"Na portrecie pracownika (upload 2020/07, więc stare) widać granatowe polo z haftowanym, ledwo czytelnym logo. Zdjęcie z podstrony Projecten to wnętrze klienta, nie dowód reklamy firmy. Floty nie udało się ustalić, więc luka jest hipotezą.",odz="POTWIERDZONE (częściowo): granatowe polo z małym logo na piersi, ledwo czytelnym; https://www.eversenevers.nl/wp-content/uploads/2020/07/Evers-Evers_Klein-4-e1595236386926-240x240.jpg, data z ścieżki: 2020/07")
add(187,"NIEUSTALONE","niska","Siłownia 24/7 w Veldhoven i Waalre, EGYM, reformer pilates; sklep/rejestracja online. Jedyne zdjęcie to wnętrze ze sprzętem.","Grafika ścienna we wnętrzu klubu","lokalna firma","Zdjęcia wnętrza i fasady klubu w Waalre; czy to część większej sieci (w stopce alt 'aqovo').",1,["https://www.cardo.nl/wp-content/uploads/2026/05/DJFL9841-2-1024x683.jpg"],"Zdjęcie (upload 2026/05) pokazuje sprzęt z logo na ekranie, ale nie ścianę ani fasadę. Brak dowodu na grafikę ścienną lub jej brak. Dwa kluby i wzmianka alt 'aqovo' sugerują możliwą wspólną markę, co trzeba sprawdzić.")
add(98,"NISKA SZANSA","wysoka","Sieć myjni ANAC (Belgia i Holandia), ok. 14 lokalizacji, w tym Eindhoven-Woensdel; własne sesje zdjęciowe i kampanie (upload 2025/12, 2026/09).","Brak (zakupy centralne)","oddział sieci","Nic do rozstrzygnięcia w kwestii decyzji: zakupy reklamy idą z centrali.",2,["https://www.anaccarwash.com/over-ons/","https://www.anaccarwash.com/wp-content/uploads/2025/09/CF_ANAC-67-683x1024.jpg"],"To sieć z jednolitą identyfikacją: pracownica w granatowym polo z logo ANAC i żółte auto z napisem adresu strony (upload 2025/09). Oddział w Eindhoven raczej nie kupuje lokalnie. Szanse są niskie.",auta="POTWIERDZONE (częściowo): żółte auto z fragmentem napisu '...RWASH.COM' na drzwiach (zdjęcie reklamowe, nie flota firmy); https://www.anaccarwash.com/wp-content/uploads/2025/09/CF_ANAC-67-683x1024.jpg, 2025/09",odz="POTWIERDZONE: granatowe polo z logo ANAC; https://www.anaccarwash.com/wp-content/uploads/2025/09/CF_ANAC-67-683x1024.jpg, data z ścieżki: 2025/09",hip=False)
