add(65,"OPCJA ROZSZERZENIA","średnia","Małe rodzinne przedsiębiorstwo ogrodnicze z szkółką (Sint-Oedenrode), ponad 25 lat; strona na gotowym szablonie, zdjęcia 'Bedrijfsbusje'.","Odzież robocza z logo","lokalna firma","Data zdjęcia busa (wygląda na starszy model); czy ekipa nosi odzież z logo; stan szyldu przy szkółce.",1,["https://www.hoveniersbedrijfhenrivanderwijst.nl/uploads/s7JwsgSc/767x0_2560x0/HoveniersbedrijfKwekerijHenrivanderWijst-OudeVresselseweg9-0017.jpg"],"Granatowy bus Mercedes ma na boku i masce logo z drzewem oraz nazwę firmy (zdjęcie bez daty). Czyli oklejenie pojedynczego busa istnieje, ale nie wiadomo o reszcie floty ani o odzieży. Luka w odzieży to hipoteza, bez sygnału z datą.",auta="POTWIERDZONE: granatowy bus z logo i nazwą 'Hoveniersbedrijf Henri van der Wijst' oraz danymi kontaktowymi na boku, z przyczepą; https://www.hoveniersbedrijfhenrivanderwijst.nl/uploads/s7JwsgSc/767x0_2560x0/HoveniersbedrijfKwekerijHenrivanderWijst-OudeVresselseweg9-0017.jpg, data nieznana")
add(223,"NISKA SZANSA","wysoka","ECHOS Home Oirschot: lokalizacja ogólnokrajowej fundacji ECHOS (ANBI, wiele Homów, 150 lat) dla wojskowych i weteranów.","Brak (organizacja ogólnokrajowa)","oddział sieci","Nic: decyzje o identyfikacji wizualnej są centralne.",1,["https://i0.wp.com/www.echos.nl/wp-content/uploads/2026/05/Team-Oirschot.jpg","https://www.echos.nl/oirschot/"],"Zespół na zdjęciu (upload 2026/05) ma już jednolite czarne polo z logo ECHOS i banery roll-up z grafiką ECHOS. To organizacja ogólnokrajowa o jednolitej marce, więc lokalna sprzedaż jest mało prawdopodobna.",odz="POTWIERDZONE: sześć osób w czarnych polo/kitlu z logo ECHOS; https://i0.wp.com/www.echos.nl/wp-content/uploads/2026/05/Team-Oirschot.jpg, data z ścieżki: 2026/05",druk="POTWIERDZONE: trójdzielny roll-up/ścianka ECHOS ('ECHOS in de tijd', 'op locatie', 'op missie') za zespołem; to samo zdjęcie, 2026/05",hip=False)
add(40,"NIEUSTALONE","niska","Elektrotechnika, instalacje medyczne, domotyka i zabezpieczenia (Helmond); działa regionalnie i krajowo; strona z logami klientów, bez zdjęć floty ani zespołu.","Oklejenie busów serwisowych","lokalna firma","Zdjęcia busów serwisowych (Street View, Google, social) i odzieży ekipy; czy to część grupy.",0,["https://heuvel-e-t.nl/bedrijfsprofiel/","https://heuvel-e-t.nl/vacatures/"],"W kodzie strony są tylko zdjęcia stockowe i logotypy klientów, więc o flocie nic nie wiadomo. Nie otwarto żadnego istotnego zdjęcia. Rekrutacja bez daty nie daje sygnału zakupowego.")
