add(207,"NIEUSTALONE","niska","Kawiarnia-bar w Eindhoven, otwarta wieczorami, imprezy studenckie i PSV; strona z nowym logo SVG i grafikami z ścieżek uploads/2026/05.","Szyld / oklejenie witryny","lokalna firma","Zdjęcia fasady (Street View) i informacja, czy nowa identyfikacja z 2026/05 oznacza zmianę szyldu.",0,["https://lempke.nl/over-ons","https://lempke.nl/werken-bij"],"Strona sprawia wrażenie świeżo odnowionej (pliki z 2026/05), ale to nie jest dowód zmiany szyldu. Brak zdjęć fasady, nic nie otwarto. Rebranding tylko online daje hipotezę, nie okazję.")
add(160,"NIEUSTALONE","niska","Sieć salonów fryzjerskich KNAP! (m.in. Boxtel), wspólna strona, podstrony vacature i haarwerken; w danych brak miasta.","Szyld / witryna salonu","nieustalone","Lista lokalizacji (czy Eindhoven jest w niej i czy to franczyza, czy własne salony) oraz zdjęcia fasad.",2,["https://www.kapsalonknap.nl/team"],"Zdjęcia, które otworzyłem, to zbliżenie fryzury i portret fryzjerki, bez reklamy zewnętrznej. Jednolity brand i wiele salonów wskazują na możliwe centralne zakupy, ale tego nie sprawdzono. Dlatego bez rozstrzygnięcia.")
add(46,"NIEUSTALONE","niska","Biuro elektrotechniczne (Eindhoven); na stronie głównej pilna wakat na elektromontera (bez daty); podstrona Projecten pusta ('wordt later aangevuld').","Oklejenie busów serwisowych","lokalna firma","Zdjęcia busów (Street View, social) i data ogłoszenia o pracy.",1,["https://www.etbvlemmix.nl/projecten/"],"Jedyne zdjęcia na stronie pochodzą z 2015 i pokazują wnętrza klientów, nie flotę. Wakat 'per direct' jest bez daty, więc nie liczy się jako sygnał zakupowy. Hipoteza: nowy monter może potrzebować odzieży i busa.")
add(125,"OPCJA ROZSZERZENIA","średnia","Szkoła jazdy z Eindhoven (65+ lat); na stronie głównej 'Rijschool Wildenberg is verhuisd' na Quinten Matsyslaan 33; sekcja nieuws.","Szyld/oklejenie witryny nowej siedziby oraz przeoklejenie aut przejętej szkoły","lokalna firma","Czy nowa siedziba ma szyld i witrynę z brandingiem; czy auta przejętej Versantvoort Rijopleidingen zostały przeoklejone (Street View, zdjęcia z otwarcia).",1,["https://www.rijschoolwildenberg.nl/post/rijsimulatorbeleving","https://www.rijschoolwildenberg.nl/blog-feed.xml","https://www.rijschoolwildenberg.nl/post/versantvoort-rijopleidingen-overgenomen-door-rijschool-wildenberg-1","https://www.rijschoolwildenberg.nl/nieuws"],"Auto szkoleniowe (Ford Puma, czarne z kolorowym wzorem i logo Wildenberg, litera L na dachu) jest już oklejone. Feed bloga datuje otwarcie nowej lokalizacji na 2 lutego 2026 oraz przejęcie Versantvoort na 9 listopada 2025. Nie ma dowodu luki, ale to najlepsze datowane okazje w paczce, więc opcja rozszerzenia.",auta="POTWIERDZONE: czarny Ford Puma z logo 'Wildenberg Mijn rijschool', kolorowym wzorem i numerem; https://static.wixstatic.com/media/345956_414662e90761460a90ec3f032b6f4bd2~mv2.jpg, data nieznana",sygnal="Otwarcie nowej lokalizacji (wpis z 2 lutego 2026): https://www.rijschoolwildenberg.nl/post/rijsimulatorbeleving; przejęcie Versantvoort Rijopleidingen (9 listopada 2025): https://www.rijschoolwildenberg.nl/post/versantvoort-rijopleidingen-overgenomen-door-rijschool-wildenberg-1 (daty z blog-feed.xml)",szyld="nieustalone: nowa siedziba ogłoszona, wygląd szyldu niepotwierdzony")
add(271,"NIEUSTALONE","niska","Biuro inżynierskie konstrukcji (Heeze), BIM, projekty; strona rekrutuje (hoofd tekenkamer, tekenaar, constructeur) bez daty.","Odzież firmowa dla zespołu","lokalna firma","Zdjęcia biura i zespołu, informacja o liczbie pracowników i terenowych ekip (inżynierowie na budowie).",0,["https://www.adviesbureau-dekker-engineering.nl/over-ons","https://www.adviesbureau-dekker-engineering.nl/vacatures/"],"Firma to biuro projektowe, więc potrzeba reklamy fizycznej jest niepewna. Nie otwarto zdjęć. Rekrutacja bez daty to tylko hipoteza.")
