add(280,"NIEUSTALONE","niska","Agencja pracy w sektorze zieleni (hovenier, greenkeeper), wiele vestigingen, opinie i blog; zdjęcia głównie stockowe/oferty pracy.","Odzież robocza lub oklejenie biura","nieustalone","Lista biur (czy Nuenen to samodzielna firma czy oddział), zdjęcia fasady biura i odzieży kandydatów.",0,["https://www.baneninhetgroen.nl/"],"Strona główna nie pokazuje floty ani szyldu. Wiele biur sugeruje strukturę sieciową, ale tego nie sprawdzono. Nie otwarto żadnych zdjęć.")
add(191,"OPCJA ROZSZERZENIA","niska","Siłownia GymBokx w Helmond (fitness, CrossFit, Hyrox), sklep online, 4 wakaty.","Szyld/witryna lub grafika zewnętrzna","lokalna firma","Zdjęcia fasady i wejścia; czy napis na ścianie to stałe wykończenie; aktualność zdjęć.",1,["https://www.gymbokx.nl/wp-content/uploads/2021/03/Fitness-742x618.jpg"],"Na zdjęciu wnętrza (ścieżka 2021/03) widać na czarnym elemencie sufitu/ściany ciemny napis przypominający GYMBOKX, więc część brandingu wnętrza jest. Fasada nie została pokazana. Zdjęcie jest stare.",szyld="POTWIERDZONE (słabo czytelne): ciemny napis 'GYMBOKX' na elemencie wnętrza; https://www.gymbokx.nl/wp-content/uploads/2021/03/Fitness-742x618.jpg, data z ścieżki: 2021/03")
add(143,"NIEUSTALONE","niska","Strona to szablon WordPress ('Just another WordPress site', wpis Hello world z 13 maja 2026) z logo 'Dak Direct Nederland, Dakdekker Veghel'; nic o PVC Atelier w Eindhoven.","Szyld lub witryna","nieustalone","Czy firma w ogóle działa pod tym adresem i w Eindhoven; inne źródła (KvK, social), zdjęcia lokalu.",0,["https://pvcatelier.nl/wp-content/uploads/2026/05/ddn-transperant.png"],"Strona jest pustym szablonem z logo innej firmy z Veghel, więc nie jest dowodem dla PVC Atelier. Nie da się nic ustalić o reklamie. Potrzebne niezależne źródło.")
add(57,"OPCJA ROZSZERZENIA","niska","Jednoosobowy hovenier Groen met Koen (Geldrop-Mierlo), tuinaanleg, zakładka Vacatures, galeria realizacji.","Oklejenie auta firmowego","lokalna firma","Zdjęcia samochodu/busa firmowego (social, Google), data zdjęcia z podstrony Over Koen.",1,["https://www.groenmetkoen.nl/over-koen/","https://www.groenmetkoen.nl/wp-content/uploads/2021/12/121696563_3368878839895352_8251187306197387468_n.jpg"],"Mężczyzna układający kostkę ma zielono-czarną koszulkę z nadrukiem na piersi, ale nadruk jest nieczytelny, więc nie przypisuję go z pewnością. Auta nie widać. Zdjęcie ma ścieżkę 2021/12.",odz="POTWIERDZONE (częściowo): zielono-czarna koszulka robocza z nieczytelnym nadrukiem; https://www.groenmetkoen.nl/wp-content/uploads/2021/12/121696563_3368878839895352_8251187306197387468_n.jpg, data z ścieżki: 2021/12")
add(111,"NIEUSTALONE","niska","Niezależna stacja APK w Waalre (przegląd okresowy), mała, prosta strona z jedną grupą zdjęć.","Szyld stacji","lokalna firma","Zdjęcie fasady (Street View) i aktualny stan szyldu; czy strona i zdjęcia są aktualne.",1,["https://www.aalstwaalreapk.nl/images/apk-aalst-waalre.jpg"],"Jedyne obejrzane zdjęcie to mechanik w czarnej koszulce z małym, nieczytelnym logo, zdjęcie bez daty i wyglądające na stare. O szyldzie i oknach nic nie wiadomo.")
add(229,"NIEUSTALONE","niska","Restauracja orientalna Kota Radja w Gemert od 1982, bufety i sushi; zdjęcia strony pochodzą z 2015 (wnętrza).","Szyld / witryna restauracji","lokalna firma","Zdjęcie fasady (Street View, Google), czy szyld był odnowiony po 2015.",1,["https://restaurantkotaradja.com/wp-content/uploads/2015/07/RestaurantKotaRadjaGemertRestaurantN.jpg"],"Obejrzane zdjęcie to wnętrze sali z 2015 (ścieżka pliku), bez elementów reklamy. Fasada nie jest pokazana, więc nie da się ocenić szyldu.")
add(231,"NIEUSTALONE","niska","Strona restariabrouwhorst.nl opisuje frietkot/restarię w centrum handlowym Brouwhorst w Helmond (nazwa w danych: Brouwhuis); prosta strona, zdjęcia w plikach wpimages.","Szyld / witryna lokalu","lokalna firma","Zdjęcie fasady w centrum handlowym; potwierdzenie, że to ta sama firma co 'Restaria Brouwhuis' w bazie.",1,["http://restariabrouwhorst.nl/contact.html"],"Jedyny otwarty obraz to tło z drewna bez treści. Nazwa na stronie (Brouwhorst) różni się od nazwy w danych (Brouwhuis), więc wymaga potwierdzenia. Reklamy fizycznej nie da się ocenić.")
